#define _fseeki64 fseeko
#define _ftelli64 ftello
#endif

typedef uint8_t u8;
typedef uint32_t u32;
typedef uint64_t u64;

/* ------------------------------------------------------------------ basics */

static void die(const char *fmt, ...)
{
    va_list ap;
    va_start(ap, fmt);
    fprintf(stderr, "f3link: ");
    vfprintf(stderr, fmt, ap);
    fprintf(stderr, "\n");
    va_end(ap);
    exit(1);
}

static time_t g_t0;
static void info(const char *fmt, ...)
{
    va_list ap;
    fprintf(stderr, "[%4ds] ", (int)(time(NULL) - g_t0));
    va_start(ap, fmt);
    vfprintf(stderr, fmt, ap);
    va_end(ap);
    fputc('\n', stderr);
}

static void *xmalloc(size_t n)
{
    void *p = malloc(n ? n : 1);
    if (!p) die("out of memory");
    return p;
}
static void *xcalloc(size_t n, size_t s)
{
    void *p = calloc(n ? n : 1, s ? s : 1);
    if (!p) die("out of memory");
    return p;
}
static void *xrealloc(void *p, size_t n)
{
    p = realloc(p, n ? n : 1);
    if (!p) die("out of memory");
    return p;
}
static char *xstrndup(const char *s, size_t n)
{
    char *p = xmalloc(n + 1);
    memcpy(p, s, n);
    p[n] = 0;
    return p;
}
static char *xstrdup(const char *s) { return xstrndup(s, strlen(s)); }

typedef struct {
    int *p;
    int n, cap;
} IVec;
static void iv_push(IVec *v, int x)
{
    if (v->n == v->cap) {
        v->cap = v->cap ? v->cap * 2 : 64;
        v->p = xrealloc(v->p, (size_t)v->cap * sizeof(int));
    }
    v->p[v->n++] = x;
}
typedef struct {
    u32 *p;
    int n, cap;
} UVec;
static void uv_push(UVec *v, u32 x)
{
    if (v->n == v->cap) {
        v->cap = v->cap ? v->cap * 2 : 64;
        v->p = xrealloc(v->p, (size_t)v->cap * sizeof(u32));
    }
    v->p[v->n++] = x;
}

/* u32 -> int open-addressing map; key 0 is never stored */
typedef struct {
    u32 *k;
    int *v;
    u32 cap, n;
} Map;
static u32 hmix(u32 x)
{
    x ^= x >> 16;
    x *= 0x7feb352dU;
    x ^= x >> 15;
    x *= 0x846ca68bU;
    x ^= x >> 16;
    return x;
}
static void map_put(Map *m, u32 key, int val);
static void map_grow(Map *m)
{
    Map o = *m;
    u32 i;
    m->cap = o.cap ? o.cap * 2 : 1024;
    m->k = xcalloc(m->cap, sizeof(u32));
    m->v = xcalloc(m->cap, sizeof(int));
    m->n = 0;
    for (i = 0; i < o.cap; i++)
        if (o.k[i]) map_put(m, o.k[i], o.v[i]);
    free(o.k);
    free(o.v);
}
static void map_put(Map *m, u32 key, int val)
{
    u32 i;
    if (!key) return;
    if ((m->n + 1) * 2 > m->cap) map_grow(m);
    i = hmix(key) & (m->cap - 1);
    while (m->k[i] && m->k[i] != key) i = (i + 1) & (m->cap - 1);
    if (!m->k[i]) m->n++;
    m->k[i] = key;
    m->v[i] = val;
}
/* put only if absent */
static void map_add(Map *m, u32 key, int val)
{
    u32 i;
    if (!key) return;
    if ((m->n + 1) * 2 > m->cap) map_grow(m);
    i = hmix(key) & (m->cap - 1);
    while (m->k[i] && m->k[i] != key) i = (i + 1) & (m->cap - 1);
    if (m->k[i]) return;
    m->n++;
    m->k[i] = key;
    m->v[i] = val;
}
static int map_get(const Map *m, u32 key, int *val)
{
    u32 i;
    if (!m->cap || !key) return 0;
    i = hmix(key) & (m->cap - 1);
    while (m->k[i]) {
        if (m->k[i] == key) {
            if (val) *val = m->v[i];
            return 1;
        }
        i = (i + 1) & (m->cap - 1);
    }
    return 0;
}

/* string intern table */
typedef struct {
    char **s;
    u32 *h, *len;
    int n, cap;
    int *slot;
    u32 scap;
} Intern;
static u32 fnv32(const char *s, size_t n)
{
    u32 h = 2166136261u;
    while (n--) {
        h ^= (u8)*s++;
        h *= 16777619u;
    }
    return h;
}
static void in_rehash(Intern *t)
{
    u32 nc = t->scap ? t->scap * 2 : 4096, j;
    int i, *ns = xcalloc(nc, sizeof(int));
    for (i = 0; i < t->n; i++) {
        j = t->h[i] & (nc - 1);
        while (ns[j]) j = (j + 1) & (nc - 1);
        ns[j] = i + 1;
    }
    free(t->slot);
    t->slot = ns;
    t->scap = nc;
}
static int in_find(Intern *t, const char *s, size_t n, int create)
{
    u32 h = fnv32(s, n), j;
    if (create && (!t->scap || (u32)(t->n + 1) * 2 > t->scap)) in_rehash(t);
    if (!t->scap) return -1;
    j = h & (t->scap - 1);
    while (t->slot[j]) {
        int id = t->slot[j] - 1;
        if (t->h[id] == h && t->len[id] == n && !memcmp(t->s[id], s, n)) return id;
        j = (j + 1) & (t->scap - 1);
    }
    if (!create) return -1;
    if (t->n == t->cap) {
        t->cap = t->cap ? t->cap * 2 : 4096;
        t->s = xrealloc(t->s, (size_t)t->cap * sizeof(char *));
        t->h = xrealloc(t->h, (size_t)t->cap * sizeof(u32));
        t->len = xrealloc(t->len, (size_t)t->cap * sizeof(u32));
    }
    t->s[t->n] = xstrndup(s, n);
    t->h[t->n] = h;
    t->len[t->n] = (u32)n;
    t->slot[j] = t->n + 1;
    return t->n++;
}
static int intern(Intern *t, const char *s) { return in_find(t, s, strlen(s), 1); }

static Intern G_str;  /* string literals (binscan escaping) */
static Intern G_tok;  /* "v:" vtable/typedesc refs, "k:" consts, "i:" imports */
static Intern G_name; /* normalized qualified names */
static Intern G_cls;  /* RTTI class names */
static Intern G_obj;  /* object files */

/* ------------------------------------------------------------------- TSV */

static char *slurp(const char *path, size_t *len)
{
    FILE *f = fopen(path, "rb");
    long long n;
    size_t r;
    char *b;
    if (!f) return NULL;
    _fseeki64(f, 0, SEEK_END);
    n = _ftelli64(f);
    _fseeki64(f, 0, SEEK_SET);
    b = xmalloc((size_t)n + 1);
    r = fread(b, 1, (size_t)n, f);
    fclose(f);
    b[r] = 0;
    if (len) *len = r;
    return b;
}

typedef struct {
    char *buf, *p, *end;
} Tsv;
static int tsv_open(Tsv *t, const char *path)
{
    size_t n;
    t->buf = slurp(path, &n);
    if (!t->buf) return 0;
    t->p = t->buf;
    t->end = t->buf + n;
    return 1;
}
#define MAXF 32
static int tsv_row(Tsv *t, char **f)
{
    char *s;
    int nf = 0;
    if (t->p >= t->end) return -1;
    s = t->p;
    f[nf++] = s;
    for (;;) {
        char c = *s;
        if (c == '\t') {
            *s = 0;
            if (nf < MAXF) f[nf++] = s + 1;
            s++;
        } else if (c == '\n' || c == 0) {
            if (s > t->buf && s[-1] == '\r') s[-1] = 0;
            if (c == '\n') {
                *s = 0;
                t->p = s + 1;
            } else
                t->p = t->end;
            break;
        } else
            s++;
    }
    { int i; for (i = nf; i < MAXF; i++) f[i] = s; } /* s points at a NUL */
    return nf;
}
static int hcol(char **h, int nh, const char *name)
{
    int i;
    for (i = 0; i < nh; i++)
        if (!strcmp(h[i], name)) return i;
    return -1;
}
#define FLD(i) ((i) >= 0 ? f[i] : "")

static u64 parse_num(const char *s)
{
    const char *p;
    if (!s || !*s) return 0;
    if (s[0] == '0' && (s[1] == 'x' || s[1] == 'X')) return strtoull(s + 2, NULL, 16);
    for (p = s; *p; p++)
        if ((*p >= 'a' && *p <= 'f') || (*p >= 'A' && *p <= 'F')) return strtoull(s, NULL, 16);
    return strtoull(s, NULL, 10);
}

/* ------------------------------------------------------------ name handling */

static int is_idc(int c) { return isalnum(c) || c == '_' || c == '$'; }

/* normalize a qualified name: drop spaces and class/struct/union/enum keywords;
   optionally strip template argument lists */
static void norm_name(const char *in, char *out, size_t cap, int strip_tmpl)
{
    size_t o = 0;
    int depth = 0;
    const char *p = in;
    static const char *kw[] = {"class ", "struct ", "union ", "enum ", NULL};
    while (*p && o + 1 < cap) {
        int k, skipped = 0;
        if (p == in || !is_idc((u8)p[-1])) {
            for (k = 0; kw[k]; k++) {
                size_t l = strlen(kw[k]);
                if (!strncmp(p, kw[k], l)) {
                    p += l;
                    skipped = 1;
                    break;
                }
            }
            if (skipped) continue;
        }
        if (strip_tmpl && !strncmp(p, "operator", 8) && !is_idc((u8)p[8])) {
            /* keep operator<, operator<< ... literally */
            const char *q = p + 8;
            while (*q && strchr("<>=!+-*/%^&|~[]()", *q) && q - p < 12) q++;
            while (p < q && o + 1 < cap) out[o++] = *p++;
            continue;
        }
        if (*p == ' ') { p++; continue; }
        if (strip_tmpl) {
            if (*p == '<') { depth++; p++; continue; }
            if (*p == '>' && depth > 0) { depth--; p++; continue; }
            if (depth > 0) { p++; continue; }
        }
        out[o++] = *p++;
    }
    out[o] = 0;
}

/* last component of a (template-stripped) qualified name */
static const char *last_comp(const char *s)
{
    const char *r = s, *p;
    for (p = s; *p; p++)
        if (p[0] == ':' && p[1] == ':') r = p + 2;
    return r;
}

/* qualified function name from an undname()-style undecorated name */
static void qual_from_undec(const char *u, char *out, size_t cap)
{
    static const char *ccs[] = {"__thiscall ", "__cdecl ", "__stdcall ", "__fastcall ", "__clrcall ",
                                "__vectorcall ", NULL};
    const char *p, *start = NULL, *q;
    int dt = 0, dp = 0, k;
    size_t n;
    if (!strchr(u, '(')) {
        const char *s = u;
        size_t l;
        if (s[0] == '_' && (isalpha((u8)s[1]) || s[1] == '_')) s++;
        else if (s[0] == '@') s++;
        l = strlen(s);
        { const char *at = strrchr(s, '@'); if (at && at > s && isdigit((u8)at[1])) l = (size_t)(at - s); }
        if (l >= cap) l = cap - 1;
        memcpy(out, s, l);
        out[l] = 0;
        return;
    }
    for (p = u; *p && !start; p++) {
        if (*p == '<') dt++;
        else if (*p == '>') dt--;
        else if (*p == '(') dp++;
        else if (*p == ')') dp--;
        else if (*p == '_' && dt <= 0 && dp <= 0) {
            for (k = 0; ccs[k]; k++)
                if (!strncmp(p, ccs[k], strlen(ccs[k]))) {
                    start = p + strlen(ccs[k]);
                    break;
                }
        }
    }
    if (!start) {
        /* no calling convention: last token before the argument list */
        const char *e = strchr(u, '(');
        start = e;
        while (start > u && start[-1] != ' ') start--;
    }
    q = start;
    dt = 0;
    while (*q) {
        if (*q == '`') {
            int d = 0;
            while (*q) {
                if (*q == '`') d++;
                else if (*q == '\'') { d--; if (d == 0) { q++; break; } }
                q++;
            }
            continue;
        }
        if (!strncmp(q, "operator", 8) && !is_idc((u8)q[8])) {
            q += 8;
            if (q[0] == '(' && q[1] == ')') q += 2;
            else while (*q && strchr("<>=!+-*/%^&|~[],", *q)) q++;
            continue;
        }
        if (*q == '<') dt++;
        else if (*q == '>') dt--;
        else if (*q == '(' && dt <= 0) break;
        q++;
    }
    n = (size_t)(q - start);
    if (n >= cap) n = cap - 1;
    memcpy(out, start, n);
    out[n] = 0;
    while (n && out[n - 1] == ' ') out[--n] = 0;
}

/* data name from an undecorated data symbol ("char * * animEnumNames") */
static void data_from_undec(const char *u, char *name, size_t ncap, char *type, size_t tcap)
{
    const char *p, *last = NULL;
    int dt = 0;
    size_t n;
    for (p = u; *p; p++) {
        if (*p == '<') dt++;
        else if (*p == '>') dt--;
        else if (*p == '`') break;
        else if (*p == ' ' && dt <= 0) last = p;
    }
    if (!last) {
        qual_from_undec(u, name, ncap);
        type[0] = 0;
        return;
    }
    n = strlen(last + 1);
    if (n >= ncap) n = ncap - 1;
    memcpy(name, last + 1, n);
    name[n] = 0;
    n = (size_t)(last - u);
    if (n >= tcap) n = tcap - 1;
    memcpy(type, u, n);
    type[n] = 0;
}

typedef struct {
    const char *qual, *dec, *obj, *src;
    int norm, tnorm, meth, objid;
} NameRec;

static char g_nb[65536], g_nb2[65536];
static void data_from_undec(const char *u, char *name, size_t ncap, char *type, size_t tcap);
static void fill_namerec(NameRec *r, const char *qual)
{
    static const char *wrap[] = {"`dynamic initializer for '", "`dynamic atexit destructor for '", NULL};
    int k;
    /* undname spells the wrapped symbol as a full declaration; reduce it to its name */
    for (k = 0; wrap[k]; k++) {
        size_t pl = strlen(wrap[k]), l = strlen(qual);
        if (!strncmp(qual, wrap[k], pl) && l > pl + 2 && strchr(qual + pl, ' ')) {
            char inner[4096], nm[4096], ty[4096], res[8192];
            size_t il = l - pl - 2;
            if (il >= sizeof inner) break;
            memcpy(inner, qual + pl, il);
            inner[il] = 0;
            data_from_undec(inner, nm, sizeof nm, ty, sizeof ty);
            snprintf(res, sizeof res, "%s%s''", wrap[k], nm);
            qual = xstrdup(res);
            break;
        }
    }
    r->qual = qual;
    norm_name(qual, g_nb, sizeof g_nb, 0);
    r->norm = intern(&G_name, g_nb);
    norm_name(qual, g_nb2, sizeof g_nb2, 1);
    r->tnorm = intern(&G_name, g_nb2);
    r->meth = intern(&G_name, last_comp(g_nb2));
}

/* ----------------------------------------------------------------- images */

typedef struct {
    int cls;
    u32 addr, off;
    int nslots;
    int *slot;
} VT;
typedef struct {
    int cls, idx, base, mdisp, pdisp;
} Base;
typedef struct {
    u32 rva;
    const char *name, *type, *fn;
    int index;
} ParamRow;

typedef struct {
    const char *id;
    char dir[600];
    int ppc, named;
    u32 base;
    int n;
    u32 *addr, *size;
    int *ninsn, *nbb, *dcn;
    u64 *hash;
    int *so, *sn, *sid;   /* strings (sorted ids per function) */
    int *co, *cn, *cid;   /* callees, in order, duplicates kept, -1 unresolved */
    int *ro, *rn, *rid;   /* callers, distinct */
    int *dro, *drn;
    u32 *dra;             /* datarefs */
    int *to, *tn, *tid;   /* tokens (sorted ids) */
    Map amap;
    /* names */
    int *no, *nn;
    NameRec *nm;
    int nnames;
    int *objid;
    Intern dec;
    int *dec_fn;
    /* vtables */
    VT *vt;
    int nvt;
    Map clsfirst;         /* cls+1 -> first vt index (vt sorted by cls, off) */
    Base *bs;
    int nbs;
    Map basefirst;        /* cls+1 -> first base row */
    /* data names */
    Map gmap;
    const char **gname, **gtype;
    int ngl;
    /* counts / users per global string and token id */
    int *strcnt, *suo, *suid;
    int *tokcnt, *tuo, *tuid;
    /* data address -> referencing functions (sorted pairs) */
    u32 *dk;
    int *dfn, ndk;
    Map dfirst;
    /* hash sort */
    int *hs;
    /* params / locals (optional) */
    ParamRow *par, *loc;
    int npar, nloc;
    Map parfirst, locfirst; /* rva -> first row (rows sorted by rva) */
} Img;

static char g_evid[600];

static void split_push_strings(char *s, IVec *v, int *cnt)
{
    int c = 0;
    while (*s) {
        char *e = strchr(s, '\x1f');
        size_t n = e ? (size_t)(e - s) : strlen(s);
        if (n) {
            iv_push(v, in_find(&G_str, s, n, 1));
            c++;
        }
        if (!e) break;
        s = e + 1;
    }
    *cnt = c;
}

static int cmp_int(const void *x, const void *y)
{
    int a = *(const int *)x, b = *(const int *)y;
    return a < b ? -1 : a > b;
}
static int sort_uniq(int *p, int n)
{
    int i, k = 0;
    if (n <= 1) return n;
    qsort(p, n, sizeof(int), cmp_int);
    for (i = 0; i < n; i++)
        if (!k || p[k - 1] != p[i]) p[k++] = p[i];
    return k;
}

static void add_tokens(char *s, char sep, char kind, IVec *v)
{
    char buf[1024];
    while (*s) {
        char *e = strchr(s, sep);
        size_t n = e ? (size_t)(e - s) : strlen(s);
        if (n && n < sizeof buf - 3) {
            buf[0] = kind;
            buf[1] = ':';
            memcpy(buf + 2, s, n);
            buf[n + 2] = 0;
            iv_push(v, intern(&G_tok, buf));
        }
        if (!e) break;
        s = e + 1;
    }
}

static void load_features(Img *I)
{
    char path[800], *f[MAXF], *h[MAXF];
    Tsv t;
    int nh, nf, i, cap = 0, n = 0;
    int c_addr, c_size, c_str, c_cal, c_dref, c_imp, c_vref, c_const, c_ninsn, c_hash, c_nbb;
    char **rs = NULL, **rc = NULL, **rd = NULL, **ri = NULL, **rv = NULL, **rk = NULL;
    IVec sv = {0}, cv = {0}, tv = {0};
    UVec dv = {0};
    snprintf(path, sizeof path, "%s/binscan/features.tsv", I->dir);
    if (!tsv_open(&t, path)) die("missing %s", path);
    nh = tsv_row(&t, h);
    c_addr = hcol(h, nh, "addr");
    c_size = hcol(h, nh, "size");
    c_str = hcol(h, nh, "strings");
    c_cal = hcol(h, nh, "callees");
    c_dref = hcol(h, nh, "datarefs");
    c_imp = hcol(h, nh, "imports");
    c_vref = hcol(h, nh, "vrefs");
    c_const = hcol(h, nh, "consts");
    c_ninsn = hcol(h, nh, "ninsn");
    c_hash = hcol(h, nh, "hash_norm");
    c_nbb = hcol(h, nh, "nbb");
    if (c_addr < 0 || c_cal < 0) die("%s: bad header", path);
    while ((nf = tsv_row(&t, f)) >= 0) {
        if (nf < 2) continue;
        if (n == cap) {
            cap = cap ? cap * 2 : 65536;
            I->addr = xrealloc(I->addr, cap * sizeof(u32));
            I->size = xrealloc(I->size, cap * sizeof(u32));
            I->ninsn = xrealloc(I->ninsn, cap * sizeof(int));
            I->nbb = xrealloc(I->nbb, cap * sizeof(int));
            I->hash = xrealloc(I->hash, cap * sizeof(u64));
            rs = xrealloc(rs, cap * sizeof(char *));
            rc = xrealloc(rc, cap * sizeof(char *));
            rd = xrealloc(rd, cap * sizeof(char *));
            ri = xrealloc(ri, cap * sizeof(char *));
            rv = xrealloc(rv, cap * sizeof(char *));
            rk = xrealloc(rk, cap * sizeof(char *));
        }
        I->addr[n] = (u32)parse_num(FLD(c_addr));
        I->size[n] = (u32)strtoul(FLD(c_size), NULL, 10);
        I->ninsn[n] = (int)strtol(FLD(c_ninsn), NULL, 10);
        I->nbb[n] = (int)strtol(FLD(c_nbb), NULL, 10);
        I->hash[n] = strtoull(FLD(c_hash), NULL, 16);
        rs[n] = FLD(c_str);
        rc[n] = FLD(c_cal);
        rd[n] = FLD(c_dref);
        ri[n] = FLD(c_imp);
        rv[n] = FLD(c_vref);
        rk[n] = FLD(c_const);
        if (n && I->addr[n] <= I->addr[n - 1]) die("%s: not sorted at 0x%08x", path, I->addr[n]);
        n++;
    }
    I->n = n;
    for (i = 0; i < n; i++) map_put(&I->amap, I->addr[i], i);
    I->so = xmalloc(n * sizeof(int));
    I->sn = xmalloc(n * sizeof(int));
    I->co = xmalloc(n * sizeof(int));
    I->cn = xmalloc(n * sizeof(int));
    I->dro = xmalloc(n * sizeof(int));
    I->drn = xmalloc(n * sizeof(int));
    I->to = xmalloc(n * sizeof(int));
    I->tn = xmalloc(n * sizeof(int));
    for (i = 0; i < n; i++) {
        int c;
        char *s;
        I->so[i] = sv.n;
        split_push_strings(rs[i], &sv, &c);
        I->sn[i] = sort_uniq(sv.p + I->so[i], c);
        sv.n = I->so[i] + I->sn[i];
        I->co[i] = cv.n;
        for (s = rc[i]; *s;) {
            char *e = strchr(s, ',');
            u32 a = (u32)strtoul(s, NULL, 16);
            int idx = -1;
            if (!map_get(&I->amap, a, &idx)) idx = -1;
            iv_push(&cv, idx);
            if (!e) break;
            s = e + 1;
        }
        I->cn[i] = cv.n - I->co[i];
        {
            int j, k, d = 0;
            for (j = 0; j < I->cn[i]; j++) {
                int x = cv.p[I->co[i] + j];
                if (x < 0) continue;
                for (k = 0; k < j; k++) if (cv.p[I->co[i] + k] == x) break;
                if (k == j) d++;
            }
            if (!I->dcn) I->dcn = xmalloc(n * sizeof(int));
            I->dcn[i] = d;
        }
        I->dro[i] = dv.n;
        for (s = rd[i]; *s;) {
            char *e = strchr(s, ',');
            uv_push(&dv, (u32)strtoul(s, NULL, 16));
            if (!e) break;
            s = e + 1;
        }
        I->drn[i] = dv.n - I->dro[i];
        I->to[i] = tv.n;
        add_tokens(rv[i], '\x1f', 'v', &tv);
        add_tokens(rk[i], ',', 'k', &tv);
        add_tokens(ri[i], '\x1f', 'i', &tv);
        c = tv.n - I->to[i];
        I->tn[i] = sort_uniq(tv.p + I->to[i], c);
        tv.n = I->to[i] + I->tn[i];
    }
    I->sid = sv.p;
    I->cid = cv.p;
    I->dra = dv.p;
    I->tid = tv.p;
    /* callers (distinct) */
    {
        int *cnt = xcalloc(n, sizeof(int)), *st = xmalloc(n * sizeof(int)), j, tot = 0;
        for (i = 0; i < n; i++) st[i] = -1;
        for (i = 0; i < n; i++)
            for (j = 0; j < I->cn[i]; j++) {
                int c = I->cid[I->co[i] + j];
                if (c >= 0 && st[c] != i) { st[c] = i; cnt[c]++; tot++; }
            }
        I->ro = xmalloc(n * sizeof(int));
        I->rn = xcalloc(n, sizeof(int));
        I->rid = xmalloc((tot + 1) * sizeof(int));
        for (i = 0, j = 0; i < n; i++) { I->ro[i] = j; j += cnt[i]; }
        for (i = 0; i < n; i++) st[i] = -1;
        for (i = 0; i < n; i++)
            for (j = 0; j < I->cn[i]; j++) {
                int c = I->cid[I->co[i] + j];
                if (c >= 0 && st[c] != i) { st[c] = i; I->rid[I->ro[c] + I->rn[c]++] = i; }
            }
        free(cnt);
        free(st);
    }
    free(rs); free(rc); free(rd); free(ri); free(rv); free(rk);
    /* the TSV buffer is kept: nothing points into it except the freed row arrays */
    free(t.buf);
}

typedef struct {
    int fn, order;
    NameRec r;
} TmpName;
static int cmp_tmpname(const void *x, const void *y)
{
    const TmpName *a = x, *b = y;
    if (a->fn != b->fn) return a->fn < b->fn ? -1 : 1;
    return a->order < b->order ? -1 : a->order > b->order;
}
static void finish_names(Img *I, TmpName *tn, int ntn)
{
    int i;
    qsort(tn, ntn, sizeof(TmpName), cmp_tmpname);
    I->no = xcalloc(I->n, sizeof(int));
    I->nn = xcalloc(I->n, sizeof(int));
    I->nm = xmalloc((ntn + 1) * sizeof(NameRec));
    I->objid = xmalloc(I->n * sizeof(int));
    for (i = 0; i < I->n; i++) I->objid[i] = -1;
    for (i = 0; i < ntn; i++) {
        int fn = tn[i].fn;
        if (!I->nn[fn]) { I->no[fn] = i; I->objid[fn] = tn[i].r.objid; }
        I->nn[fn]++;
        I->nm[i] = tn[i].r;
        if (tn[i].r.dec && tn[i].r.dec[0]) {
            int before = I->dec.n, id = in_find(&I->dec, tn[i].r.dec, strlen(tn[i].r.dec), 1);
            if (I->dec.n > before) {
                I->dec_fn = xrealloc(I->dec_fn, (size_t)I->dec.cap * sizeof(int));
                I->dec_fn[id] = fn;
            }
        }
    }
    I->nnames = ntn;
    I->named = 1;
}

static int obj_id(const char *o)
{
    char b[600];
    size_t i, n = strlen(o);
    if (!n) return -1;
    if (n >= sizeof b) n = sizeof b - 1;
    for (i = 0; i < n; i++) b[i] = (char)tolower((u8)o[i]);
    b[n] = 0;
    return intern(&G_obj, b);
}

static void load_pdb_names(Img *I)
{
    char path[800], *f[MAXF], *h[MAXF];
    Tsv t;
    int nh, nf, ntn = 0, cap = 0, miss = 0;
    int c_rva, c_name, c_dec, c_obj, c_src;
    TmpName *tn = NULL;
    snprintf(path, sizeof path, "%s/functions.tsv", I->dir);
    if (!tsv_open(&t, path)) { info("%s: no functions.tsv (unnamed)", I->id); return; }
    nh = tsv_row(&t, h);
    c_rva = hcol(h, nh, "rva");
    c_name = hcol(h, nh, "name");
    c_dec = hcol(h, nh, "decorated");
    c_obj = hcol(h, nh, "object");
    c_src = hcol(h, nh, "source_file");
    while ((nf = tsv_row(&t, f)) >= 0) {
        int fn;
        u32 a;
        if (nf < 3) continue;
        a = I->base + (u32)parse_num(FLD(c_rva));
        if (!map_get(&I->amap, a, &fn)) { miss++; continue; }
        if (ntn == cap) { cap = cap ? cap * 2 : 65536; tn = xrealloc(tn, cap * sizeof(TmpName)); }
        tn[ntn].fn = fn;
        tn[ntn].order = ntn;
        fill_namerec(&tn[ntn].r, FLD(c_name));
        tn[ntn].r.dec = FLD(c_dec);
        tn[ntn].r.obj = FLD(c_obj);
        tn[ntn].r.src = FLD(c_src);
        tn[ntn].r.objid = obj_id(FLD(c_obj));
        ntn++;
    }
    finish_names(I, tn, ntn);
    free(tn);
    info("%s: %d names (%d rows not at a function start)", I->id, ntn, miss);
}

static void load_map_names(Img *I)
{
    char path[800], *f[MAXF], *h[MAXF], q[4096];
    Tsv t;
    int nh, nf, ntn = 0, cap = 0, ndata = 0;
    int c_va, c_dec, c_und, c_obj, c_isf, c_lib;
    TmpName *tn = NULL;
    snprintf(path, sizeof path, "%s/publics.tsv", I->dir);
    if (!tsv_open(&t, path)) die("missing %s", path);
    nh = tsv_row(&t, h);
    c_va = hcol(h, nh, "va");
    c_dec = hcol(h, nh, "decorated");
    c_und = hcol(h, nh, "undecorated");
    c_obj = hcol(h, nh, "object");
    c_isf = hcol(h, nh, "is_function");
    c_lib = hcol(h, nh, "lib");
    while ((nf = tsv_row(&t, f)) >= 0) {
        int fn;
        u32 a;
        if (nf < 5) continue;
        a = (u32)parse_num(FLD(c_va));
        if (!a) continue;
        if (!strcmp(FLD(c_isf), "1")) {
            if (!map_get(&I->amap, a, &fn)) continue;
            if (ntn == cap) { cap = cap ? cap * 2 : 65536; tn = xrealloc(tn, cap * sizeof(TmpName)); }
            qual_from_undec(FLD(c_und), q, sizeof q);
            tn[ntn].fn = fn;
            tn[ntn].order = ntn;
            fill_namerec(&tn[ntn].r, xstrdup(q));
            tn[ntn].r.dec = FLD(c_dec);
            tn[ntn].r.obj = FLD(c_obj);
            tn[ntn].r.src = FLD(c_lib);
            tn[ntn].r.objid = obj_id(FLD(c_obj));
            ntn++;
        } else {
            char nm[4096], ty[4096];
            int gi;
            if (map_get(&I->gmap, a, &gi)) continue;
            if (FLD(c_und)[0] == 0 || strchr(FLD(c_und), '`')) continue;
            data_from_undec(FLD(c_und), nm, sizeof nm, ty, sizeof ty);
            if (I->ngl % 4096 == 0) {
                I->gname = xrealloc(I->gname, (I->ngl + 4096) * sizeof(char *));
                I->gtype = xrealloc(I->gtype, (I->ngl + 4096) * sizeof(char *));
            }
            I->gname[I->ngl] = xstrdup(nm);
            I->gtype[I->ngl] = xstrdup(ty);
            map_put(&I->gmap, a, I->ngl++);
            ndata++;
        }
    }
    finish_names(I, tn, ntn);
    free(tn);
    info("%s: %d function names, %d data names (MAP)", I->id, ntn, ndata);
}

static void load_pdb_globals(Img *I)
{
    char path[800], *f[MAXF], *h[MAXF];
    Tsv t;
    int nh, nf, c_rva, c_name, c_type;
    snprintf(path, sizeof path, "%s/globals.tsv", I->dir);
    if (!tsv_open(&t, path)) return;
    nh = tsv_row(&t, h);
    c_rva = hcol(h, nh, "rva");
    c_name = hcol(h, nh, "name");
    c_type = hcol(h, nh, "type");
    while ((nf = tsv_row(&t, f)) >= 0) {
        u32 a;
        int gi;
        if (nf < 3) continue;
        a = I->base + (u32)parse_num(FLD(c_rva));
        if (map_get(&I->gmap, a, &gi)) continue;
        if (I->ngl % 4096 == 0) {
            I->gname = xrealloc(I->gname, (I->ngl + 4096) * sizeof(char *));
            I->gtype = xrealloc(I->gtype, (I->ngl + 4096) * sizeof(char *));
        }
        I->gname[I->ngl] = FLD(c_name);
        I->gtype[I->ngl] = FLD(c_type);
        map_put(&I->gmap, a, I->ngl++);
    }
}

static int cmp_paramrow(const void *x, const void *y)
{
    const ParamRow *a = x, *b = y;
    if (a->rva != b->rva) return a->rva < b->rva ? -1 : 1;
    return a->index < b->index ? -1 : a->index > b->index;
}
static void load_params(Img *I, int locals)
{
    char path[800], *f[MAXF], *h[MAXF];
    Tsv t;
    int nh, nf, n = 0, cap = 0, i, c_rva, c_idx, c_name, c_type, c_fn, c_kind;
    ParamRow *r = NULL;
    snprintf(path, sizeof path, "%s/%s.tsv", I->dir, locals ? "locals" : "params");
    if (!tsv_open(&t, path)) { info("%s: missing %s", I->id, path); return; }
    nh = tsv_row(&t, h);
    c_rva = hcol(h, nh, "function_rva");
    c_idx = hcol(h, nh, "index");
    c_name = hcol(h, nh, "name");
    c_type = hcol(h, nh, "type");
    c_fn = hcol(h, nh, "function");
    c_kind = hcol(h, nh, "kind");
    while ((nf = tsv_row(&t, f)) >= 0) {
        if (nf < 3) continue;
        if (locals && c_kind >= 0 && strcmp(FLD(c_kind), "local")) continue;
        if (n == cap) { cap = cap ? cap * 2 : 65536; r = xrealloc(r, cap * sizeof(ParamRow)); }
        r[n].rva = (u32)parse_num(FLD(c_rva));
        r[n].index = locals ? n : (int)strtol(FLD(c_idx), NULL, 10);
        r[n].name = FLD(c_name);
        r[n].type = FLD(c_type);
        r[n].fn = FLD(c_fn);
        n++;
    }
    qsort(r, n, sizeof(ParamRow), cmp_paramrow);
    for (i = n - 1; i >= 0; i--) map_put(locals ? &I->locfirst : &I->parfirst, r[i].rva + 1, i);
    if (locals) { I->loc = r; I->nloc = n; } else { I->par = r; I->npar = n; }
}

static int cmp_vt(const void *x, const void *y)
{
    const VT *a = x, *b = y;
    if (a->cls != b->cls) return a->cls < b->cls ? -1 : 1;
    if (a->off != b->off) return a->off < b->off ? -1 : 1;
    return a->addr < b->addr ? -1 : a->addr > b->addr;
}
static void load_vtables(Img *I)
{
    char path[800], *f[MAXF], *h[MAXF];
    Tsv t;
    int nh, nf, cap = 0, i;
    Map vm = {0};
    snprintf(path, sizeof path, "%s/binscan/rtti.tsv", I->dir);
    if (!tsv_open(&t, path)) return;
    nh = tsv_row(&t, h);
    {
        int c_cls = hcol(h, nh, "class"), c_vt = hcol(h, nh, "vtable_addr"), c_off = hcol(h, nh, "offset"),
            c_ns = hcol(h, nh, "nslots");
        while ((nf = tsv_row(&t, f)) >= 0) {
            VT *v;
            if (nf < 5 || !*FLD(c_vt)) continue;
            if (I->nvt == cap) { cap = cap ? cap * 2 : 4096; I->vt = xrealloc(I->vt, cap * sizeof(VT)); }
            v = &I->vt[I->nvt];
            v->cls = intern(&G_cls, FLD(c_cls));
            v->addr = (u32)parse_num(FLD(c_vt));
            v->off = (u32)parse_num(FLD(c_off));
            v->nslots = (int)strtol(FLD(c_ns), NULL, 10);
            v->slot = xmalloc((v->nslots + 1) * sizeof(int));
            for (i = 0; i < v->nslots; i++) v->slot[i] = -1;
            I->nvt++;
        }
    }
    free(t.buf);
    qsort(I->vt, I->nvt, sizeof(VT), cmp_vt);
    for (i = 0; i < I->nvt; i++) map_put(&vm, I->vt[i].addr, i);
    for (i = I->nvt - 1; i >= 0; i--) map_put(&I->clsfirst, (u32)I->vt[i].cls + 1, i);
    snprintf(path, sizeof path, "%s/binscan/vtable.tsv", I->dir);
    if (tsv_open(&t, path)) {
        int c_vt, c_slot, c_fn, vi, fi;
        nh = tsv_row(&t, h);
        c_vt = hcol(h, nh, "vtable_addr");
        c_slot = hcol(h, nh, "slot");
        c_fn = hcol(h, nh, "func");
        while ((nf = tsv_row(&t, f)) >= 0) {
            int s;
            if (nf < 5) continue;
            if (!map_get(&vm, (u32)parse_num(FLD(c_vt)), &vi)) continue;
            s = (int)strtol(FLD(c_slot), NULL, 10);
            if (s < 0 || s >= I->vt[vi].nslots) continue;
            if (map_get(&I->amap, (u32)parse_num(FLD(c_fn)), &fi)) I->vt[vi].slot[s] = fi;
        }
        free(t.buf);
    }
    snprintf(path, sizeof path, "%s/binscan/rtti_bases.tsv", I->dir);
    if (tsv_open(&t, path)) {
        int c_cls, c_idx, c_base, c_md, c_pd;
        cap = 0;
        nh = tsv_row(&t, h);
        c_cls = hcol(h, nh, "class");
        c_idx = hcol(h, nh, "index");
        c_base = hcol(h, nh, "base");
        c_md = hcol(h, nh, "mdisp");
        c_pd = hcol(h, nh, "pdisp");
        while ((nf = tsv_row(&t, f)) >= 0) {
            Base *b;
            if (nf < 6) continue;
            if (I->nbs == cap) { cap = cap ? cap * 2 : 8192; I->bs = xrealloc(I->bs, cap * sizeof(Base)); }
            b = &I->bs[I->nbs++];
            b->cls = intern(&G_cls, FLD(c_cls));
            b->idx = (int)strtol(FLD(c_idx), NULL, 10);
            b->base = intern(&G_cls, FLD(c_base));
            b->mdisp = (int)strtol(FLD(c_md), NULL, 10);
            b->pdisp = (int)strtol(FLD(c_pd), NULL, 10);
        }
        free(t.buf);
        for (i = I->nbs - 1; i >= 0; i--) map_put(&I->basefirst, (u32)I->bs[i].cls + 1, i);
    }
    free(vm.k);
    free(vm.v);
}

static Img *load_image(const char *id, int ppc, u32 base, int names)
{
    Img *I = xcalloc(1, sizeof(Img));
    I->id = id;
    I->ppc = ppc;
    I->base = base;
    snprintf(I->dir, sizeof I->dir, "%s/%s", g_evid, id);
    if (names == 1) {
        /* image base from the pdbdump header (image.txt) */
        char p[800], *b, *q;
        snprintf(p, sizeof p, "%s/image.txt", I->dir);
        if ((b = slurp(p, NULL)) != NULL) {
            if ((q = strstr(b, "image_base: ")) != NULL) I->base = (u32)strtoull(q + 12, NULL, 16);
            free(b);
        }
    }
    load_features(I);
    load_vtables(I);
    if (names == 1) { load_pdb_names(I); load_pdb_globals(I); }
    if (names == 2) load_map_names(I);
    info("%s: %d functions, %d vtables", id, I->n, I->nvt);
    return I;
}

/* per-image counts and user lists over the final string/token id spaces */
static void build_csr(int n, const int *o, const int *cnt, const int *ids, int nid, int **pcnt, int **poff,
                      int **pusers)
{
    int *c = xcalloc(nid + 1, sizeof(int)), *off = xmalloc((nid + 1) * sizeof(int)), *u, *fill, i, j, tot = 0;
    for (i = 0; i < n; i++)
        for (j = 0; j < cnt[i]; j++) c[ids[o[i] + j]]++;
    for (i = 0; i < nid; i++) { off[i] = tot; tot += c[i]; }
    off[nid] = tot;
    u = xmalloc((tot + 1) * sizeof(int));
    fill = xcalloc(nid + 1, sizeof(int));
    for (i = 0; i < n; i++)
        for (j = 0; j < cnt[i]; j++) { int s = ids[o[i] + j]; u[off[s] + fill[s]++] = i; }
    free(fill);
    *pcnt = c;
    *poff = off;
    *pusers = u;
}

static Img *g_hsort_img;
static int cmp_hs(const void *x, const void *y)
{
    u64 a = g_hsort_img->hash[*(const int *)x], b = g_hsort_img->hash[*(const int *)y];
    return a < b ? -1 : a > b;
}
static int cmp_u64(const void *x, const void *y)
{
    u64 a = *(const u64 *)x, b = *(const u64 *)y;
    return a < b ? -1 : a > b;
}
static void finish_image(Img *I)
{
    int i;
    build_csr(I->n, I->so, I->sn, I->sid, G_str.n, &I->strcnt, &I->suo, &I->suid);
    build_csr(I->n, I->to, I->tn, I->tid, G_tok.n, &I->tokcnt, &I->tuo, &I->tuid);
    I->hs = xmalloc(I->n * sizeof(int));
    for (i = 0; i < I->n; i++) I->hs[i] = i;
    g_hsort_img = I;
    qsort(I->hs, I->n, sizeof(int), cmp_hs);
    /* data index */
    {
        int tot = 0, k = 0, j;
        u64 *pr;
        for (i = 0; i < I->n; i++) tot += I->drn[i];
        pr = xmalloc((tot + 1) * sizeof(u64));
        for (i = 0; i < I->n; i++)
            for (j = 0; j < I->drn[i]; j++) pr[k++] = ((u64)I->dra[I->dro[i] + j] << 32) | (u32)i;
        qsort(pr, k, sizeof(u64), cmp_u64);
        I->dk = xmalloc((k + 1) * sizeof(u32));
        I->dfn = xmalloc((k + 1) * sizeof(int));
        I->ndk = 0;
        for (j = 0; j < k; j++) {
            if (I->ndk && pr[j] == pr[j - 1]) continue;
            I->dk[I->ndk] = (u32)(pr[j] >> 32);
            I->dfn[I->ndk] = (int)(u32)pr[j];
            I->ndk++;
        }
        for (j = I->ndk - 1; j >= 0; j--) map_put(&I->dfirst, I->dk[j], j);
        free(pr);
    }
}

/* --------------------------------------------------------- string filters */

static u8 *g_generic; /* per G_str id */

static int str_is_generic(const char *s)
{
    size_t n = strlen(s);
    int letters = 0;
    const char *p;
    char low[2048];
    size_t i;
    static const char *plat[] = {"game:", "xbox", "xenon", "x360", ":\\\\", "\\\\_fallout3", ".cpp", ".pdb",
                                 "devkit:", "cache:", "update:", "d3d", "%s(%d)", NULL};
    if (n < 6) return 1;
    for (p = s; *p; p++) {
        if (*p == '%') {
            p++;
            while (*p && strchr("-+ #0123456789.*hlLIjzt", *p)) p++;
            if (!*p) break;
            continue;
        }
        if (*p == '\\' && p[1] == 'x') { p += 3; continue; }
        if (*p == '\\') { p++; continue; }
        if (isalpha((u8)*p)) letters++;
    }
    if (letters < 3) return 1;
    if (n >= sizeof low) n = sizeof low - 1;
    for (i = 0; i < n; i++) low[i] = (char)tolower((u8)s[i]);
    low[n] = 0;
    for (i = 0; plat[i]; i++)
        if (strstr(low, plat[i])) return 1;
    return 0;
}

/* ---------------------------------------------------------------- matcher */

enum {
    M_NONE, M_VT, M_VTP, M_USTR, M_UVREF, M_HASH, M_STRSET, M_UCONST, M_UIMP,
    M_CSEQ, M_CDEDUP, M_CGAP, M_CALLER, M_USTRREL, M_CGAPSIM, M_CSIM, M_RSIM, M_OBJRUN, M_OBJSIM, M_OBJPROP,
    M_OBJOPEN, M_OPENPROP, M_UDATA, M_BRIDGE, M_PROTO_GB, M_PROTO_HK, NM
};
static const char *MN[NM] = {"none", "vtable", "vtable_prefix", "ustr", "uvref", "hash", "strset", "uconst",
                             "uimport", "call_seq", "call_dedup", "call_gap", "caller", "ustr_rel", "call_gap_sim",
                             "callee_sim", "caller_sim", "objrun", "objrun_sim", "objrun_prop", "objrun_open",
                             "objopen_prop", "udata", "bridge_fnvpc", "proto_gamebryo", "proto_havok"};
static int is_anchor(int m) { return m >= M_VT && m <= M_UIMP; }

typedef struct {
    int a, b;
    float w;
} Prop;

typedef struct {
    Img *A, *B;
    int *la, *lb;
    u8 *meth;
    u8 *hideA;
    int phase2; /* 0 anchors+graph, 1 object runs, 2 open-ended object runs */
    Prop *pp;
    int np, pcap;
    /* scratch */
    int *stA, *cntA, *lastA, *stB, *cntB, *lastB, stamp;
    int *rbA, *rst, rstamp;
    float *rw1, *rw2;
    int *buf1, *buf2, *buf3, bcap;
    double szscale, inscale;
    long contra[NM], rejc[NM], acc[NM];
} Ctx;

static Ctx *ctx_new(Img *A, Img *B)
{
    Ctx *c = xcalloc(1, sizeof(Ctx));
    int i;
    c->A = A;
    c->B = B;
    c->la = xmalloc(A->n * sizeof(int));
    c->lb = xmalloc(B->n * sizeof(int));
    for (i = 0; i < A->n; i++) c->la[i] = -1;
    for (i = 0; i < B->n; i++) c->lb[i] = -1;
    c->meth = xcalloc(A->n, 1);
    c->stA = xcalloc(A->n, sizeof(int));
    c->cntA = xcalloc(A->n, sizeof(int));
    c->lastA = xcalloc(A->n, sizeof(int));
    c->stB = xcalloc(B->n, sizeof(int));
    c->cntB = xcalloc(B->n, sizeof(int));
    c->lastB = xcalloc(B->n, sizeof(int));
    c->rbA = xcalloc(B->n, sizeof(int));
    c->rst = xcalloc(B->n, sizeof(int));
    c->rw1 = xcalloc(B->n, sizeof(float));
    c->rw2 = xcalloc(B->n, sizeof(float));
    c->bcap = 1 << 16;
    c->buf1 = xmalloc(c->bcap * sizeof(int));
    c->buf2 = xmalloc(c->bcap * sizeof(int));
    c->buf3 = xmalloc(c->bcap * sizeof(int));
    return c;
}
static void ctx_free(Ctx *c)
{
    free(c->la); free(c->lb); free(c->meth); free(c->stA); free(c->cntA); free(c->lastA);
    free(c->stB); free(c->cntB); free(c->lastB); free(c->rbA); free(c->rst); free(c->rw1); free(c->rw2);
    free(c->buf1); free(c->buf2); free(c->buf3); free(c->pp);
    free(c);
}

static void add_prop(Ctx *c, int a, int b, float w, int m)
{
    if (a < 0 || b < 0) return;
    if (c->hideA && c->hideA[a] && is_anchor(m)) return;
    if (c->la[a] >= 0 || c->lb[b] >= 0) {
        if (c->la[a] != b) c->contra[m]++;
        return;
    }
    if (c->np == c->pcap) {
        c->pcap = c->pcap ? c->pcap * 2 : 65536;
        c->pp = xrealloc(c->pp, (size_t)c->pcap * sizeof(Prop));
    }
    c->pp[c->np].a = a;
    c->pp[c->np].b = b;
    c->pp[c->np].w = w;
    c->np++;
}

/* shared-vocabulary strings of x (non-generic, present in Y); X's lists are sorted */
static int svocab(Img *X, Img *Y, int x, int *out, int cap)
{
    int i, k = 0;
    for (i = 0; i < X->sn[x] && k < cap; i++) {
        int s = X->sid[X->so[x] + i];
        if (!g_generic[s] && Y->strcnt[s] > 0) out[k++] = s;
    }
    return k;
}
static int tvocab(Img *X, Img *Y, int x, int *out, int cap)
{
    int i, k = 0;
    for (i = 0; i < X->tn[x] && k < cap; i++) {
        int s = X->tid[X->to[x] + i];
        if (G_tok.s[s][0] == 'v' && Y->tokcnt[s] > 0) out[k++] = s;
    }
    return k;
}
static int inter_sorted(const int *a, int na, const int *b, int nb)
{
    int i = 0, j = 0, r = 0;
    while (i < na && j < nb) {
        if (a[i] == b[j]) { r++; i++; j++; }
        else if (a[i] < b[j]) i++;
        else j++;
    }
    return r;
}

static int compat(Ctx *c, int a, int b)
{
    Img *A = c->A, *B = c->B;
    double r = (double)(B->size[b] + 1) / (double)(A->size[a] + 1);
    int sa[256], sb[256], na, nb, in;
    if (!(r >= 0.33 && r <= 3.0)) {
        int d = A->ninsn[a] - B->ninsn[b];
        if (d < -3 || d > 3) return 0;
    }
    na = svocab(A, B, a, sa, 256);
    nb = svocab(B, A, b, sb, 256);
    in = inter_sorted(sa, na, sb, nb);
    if (na && nb && !in) return 0;
    if ((na >= 3 && !nb) || (nb >= 3 && !na)) return 0;
    na = tvocab(A, B, a, sa, 256);
    nb = tvocab(B, A, b, sb, 256);
    in = inter_sorted(sa, na, sb, nb);
    if (na && nb && !in) return 0;
    return 1;
}

static void do_link(Ctx *c, int a, int b, int m)
{
    c->la[a] = b;
    c->lb[b] = a;
    if (c->phase2 == 1 && m != M_OBJRUN && m != M_OBJSIM) m = M_OBJPROP;
    if (c->phase2 == 2 && m != M_OBJOPEN) m = M_OPENPROP;
    c->meth[a] = (u8)m;
    c->acc[m]++;
}

static int cmp_prop(const void *x, const void *y)
{
    const Prop *p = x, *q = y;
    if (p->a != q->a) return p->a < q->a ? -1 : 1;
    return p->b < q->b ? -1 : p->b > q->b;
}
#define UNANIMOUS 1e9
static int resolve(Ctx *c, int m, double ratio, int chk)
{
    int i, j, k, n, acc = 0;
    if (!c->np) return 0;
    qsort(c->pp, c->np, sizeof(Prop), cmp_prop);
    for (i = 0, k = 0; i < c->np; i++) {
        if (k && c->pp[k - 1].a == c->pp[i].a && c->pp[k - 1].b == c->pp[i].b) c->pp[k - 1].w += c->pp[i].w;
        else c->pp[k++] = c->pp[i];
    }
    n = k;
    c->rstamp++;
    for (i = 0; i < n; i++) {
        int b = c->pp[i].b;
        float w = c->pp[i].w;
        if (c->rst[b] != c->rstamp) {
            c->rst[b] = c->rstamp;
            c->rbA[b] = c->pp[i].a;
            c->rw1[b] = w;
            c->rw2[b] = 0;
        } else if (w > c->rw1[b]) {
            c->rw2[b] = c->rw1[b];
            c->rw1[b] = w;
            c->rbA[b] = c->pp[i].a;
        } else if (w > c->rw2[b])
            c->rw2[b] = w;
    }
    for (i = 0; i < n; i = j) {
        int a = c->pp[i].a, bb = -1;
        float w1 = 0, w2 = 0;
        for (j = i; j < n && c->pp[j].a == a; j++) {
            float w = c->pp[j].w;
            if (w > w1) { w2 = w1; w1 = w; bb = c->pp[j].b; }
            else if (w > w2) w2 = w;
        }
        if (bb < 0 || c->rbA[bb] != a) continue;
        if (!(w1 > w2 && w1 >= ratio * w2)) continue;
        if (!(c->rw1[bb] > c->rw2[bb] && c->rw1[bb] >= ratio * c->rw2[bb])) continue;
        if (c->la[a] >= 0 || c->lb[bb] >= 0) continue;
        if (chk && !compat(c, a, bb)) { c->rejc[m]++; continue; }
        do_link(c, a, bb, m);
        acc++;
    }
    c->np = 0;
    return acc;
}

/* --- anchors */

static int vt_primary_nslots(Img *I, int cls)
{
    int i;
    if (!map_get(&I->clsfirst, (u32)cls + 1, &i)) return -1;
    for (; i < I->nvt && I->vt[i].cls == cls; i++)
        if (I->vt[i].off == 0) return I->vt[i].nslots;
    return -1;
}
static int vt_prefix_len(Img *A, Img *B, int cls, u32 off)
{
    int i, L = 0;
    if (!map_get(&A->basefirst, (u32)cls + 1, &i)) return 0;
    for (; i < A->nbs && A->bs[i].cls == cls; i++) {
        Base *b = &A->bs[i];
        int na, nb;
        if (b->idx == 0 || b->base == cls || (u32)b->mdisp != off || b->pdisp != -1) continue;
        na = vt_primary_nslots(A, b->base);
        nb = vt_primary_nslots(B, b->base);
        if (na > 0 && na == nb && na > L) L = na;
    }
    return L;
}
/* pair the vtables of one class on both sides; calls fn(va, vb) */
static int vt_pair(Img *A, Img *B, int ia, int *out_ib)
{
    int cls = A->vt[ia].cls, fa, fb, na = 0, nb = 0, i, k;
    if (!map_get(&A->clsfirst, (u32)cls + 1, &fa)) return 0;
    if (!map_get(&B->clsfirst, (u32)cls + 1, &fb)) return 0;
    while (fa + na < A->nvt && A->vt[fa + na].cls == cls) na++;
    while (fb + nb < B->nvt && B->vt[fb + nb].cls == cls) nb++;
    k = ia - fa;
    if (na == nb) { *out_ib = fb + k; return 1; }
    for (i = 0; i < nb; i++)
        if (B->vt[fb + i].off == A->vt[ia].off) { *out_ib = fb + i; return 1; }
    return 0;
}
static int m_vtables(Ctx *c, int prefix)
{
    Img *A = c->A, *B = c->B;
    int ia, ib, k;
    for (ia = 0; ia < A->nvt; ia++) {
        VT *va = &A->vt[ia], *vb;
        if (!vt_pair(A, B, ia, &ib)) continue;
        vb = &B->vt[ib];
        if (!prefix) {
            if (va->nslots != vb->nslots) continue;
            for (k = 0; k < va->nslots; k++) add_prop(c, va->slot[k], vb->slot[k], 1, M_VT);
        } else {
            int L;
            if (va->nslots == vb->nslots) continue;
            L = vt_prefix_len(A, B, va->cls, va->off);
            if (L > va->nslots) L = va->nslots;
            if (L > vb->nslots) L = vb->nslots;
            for (k = 0; k < L; k++) add_prop(c, va->slot[k], vb->slot[k], 1, M_VTP);
        }
    }
    return resolve(c, prefix ? M_VTP : M_VT, 3.0, 1);
}

static int m_ustr(Ctx *c)
{
    Img *A = c->A, *B = c->B;
    int s;
    for (s = 0; s < G_str.n; s++)
        if (!g_generic[s] && A->strcnt[s] == 1 && B->strcnt[s] == 1)
            add_prop(c, A->suid[A->suo[s]], B->suid[B->suo[s]], 1, M_USTR);
    return resolve(c, M_USTR, 2.0, 1);
}
static int m_utok(Ctx *c, char kind, int m)
{
    Img *A = c->A, *B = c->B;
    int s;
    for (s = 0; s < G_tok.n; s++) {
        const char *t = G_tok.s[s];
        if (t[0] != kind || A->tokcnt[s] != 1 || B->tokcnt[s] != 1) continue;
        if (kind == 'k') {
            /* skip small/common-looking float constants: need >= 3 significant hex digits */
            const char *p = t + 2;
            if (*p == 'f' || *p == 'd') {
                size_t l = strlen(p + 1), z = 0;
                while (l > 0 && p[1 + l - 1] == '0') { l--; z++; }
                if (l < 4) continue;
            }
        }
        add_prop(c, A->tuid[A->tuo[s]], B->tuid[B->tuo[s]], 1, m);
    }
    return resolve(c, m, 2.0, 1);
}
static int m_hash(Ctx *c)
{
    Img *A = c->A, *B = c->B;
    int i, j;
    if (A->ppc || B->ppc) return 0;
    for (i = 0, j = 0; i < A->n; i++) {
        int a = A->hs[i];
        u64 h = A->hash[a];
        if ((i > 0 && A->hash[A->hs[i - 1]] == h) || (i + 1 < A->n && A->hash[A->hs[i + 1]] == h)) continue;
        if (A->size[a] < 24) continue;
        while (j < B->n && B->hash[B->hs[j]] < h) j++;
        if (j >= B->n || B->hash[B->hs[j]] != h) continue;
        if (j + 1 < B->n && B->hash[B->hs[j + 1]] == h) continue;
        if (B->size[B->hs[j]] < 24) continue;
        add_prop(c, a, B->hs[j], 1, M_HASH);
    }
    return resolve(c, M_HASH, UNANIMOUS, 1);
}

static int strset_best(Ctx *c, int dirAB, int x, double *J1, double *J2)
{
    Img *X = dirAB ? c->A : c->B, *Y = dirAB ? c->B : c->A;
    int *ly = dirAB ? c->lb : c->la, *stY = dirAB ? c->stB : c->stA;
    int *sx = c->buf1, *cand = c->buf2, *sy = c->buf3;
    int nx, ny, ncand = 0, i, j, best = -1;
    double b1 = 0, b2 = 0;
    nx = svocab(X, Y, x, sx, 4096);
    if (nx < 3) return -1;
    c->stamp++;
    for (i = 0; i < nx; i++) {
        int s = sx[i];
        if (Y->strcnt[s] > 200) continue;
        for (j = 0; j < Y->strcnt[s] && ncand < c->bcap; j++) {
            int y = Y->suid[Y->suo[s] + j];
            if (ly[y] >= 0 || stY[y] == c->stamp) continue;
            stY[y] = c->stamp;
            cand[ncand++] = y;
        }
    }
    for (i = 0; i < ncand; i++) {
        int y = cand[i], in;
        double J;
        ny = svocab(Y, X, y, sy, 4096);
        if (ny < 3) continue;
        in = inter_sorted(sx, nx, sy, ny);
        J = (double)in / (double)(nx + ny - in);
        if (J > b1) { b2 = b1; b1 = J; best = y; }
        else if (J > b2) b2 = J;
    }
    *J1 = b1;
    *J2 = b2;
    return b1 >= 0.8 ? best : -1;
}
static int m_strset(Ctx *c)
{
    Img *A = c->A;
    int a;
    for (a = 0; a < A->n; a++) {
        double j1, j2, k1, k2;
        int b;
        if (c->la[a] >= 0 || A->sn[a] < 3) continue;
        if (c->hideA && c->hideA[a]) continue;
        b = strset_best(c, 1, a, &j1, &j2);
        if (b < 0 || !(j1 > j2)) continue;
        if (strset_best(c, 0, b, &k1, &k2) != a || !(k1 > k2)) continue;
        add_prop(c, a, b, 1, M_STRSET);
    }
    return resolve(c, M_STRSET, UNANIMOUS, 1);
}

/* --- propagation */

static void prop_aligned(Ctx *c, const int *xa, const int *yb, int n, int m)
{
    int i, bad = 0;
    for (i = 0; i < n; i++) {
        int x = xa[i], y = yb[i];
        if (x < 0 || y < 0) continue;
        if (c->la[x] >= 0 && c->la[x] != y) bad++;
        else if (c->lb[y] >= 0 && c->lb[y] != x) bad++;
    }
    if (bad) return;
    for (i = 0; i < n; i++) {
        int x = xa[i], y = yb[i];
        if (x >= 0 && y >= 0 && c->la[x] < 0 && c->lb[y] < 0) add_prop(c, x, y, 1, m);
    }
}
static int dedup_list(const int *l, int n, int *out, int *st, int stamp)
{
    int i, k = 0;
    for (i = 0; i < n; i++) {
        int x = l[i];
        if (x < 0 || st[x] == stamp) continue;
        st[x] = stamp;
        out[k++] = x;
    }
    return k;
}
static void align_lists(Ctx *c, const int *xa, int na, const int *yb, int nb, double TT, int m);
static double g_sim_T;
static int m_calls(Ctx *c, int m)
{
    Img *A = c->A, *B = c->B;
    int a;
    for (a = 0; a < A->n; a++) {
        int b = c->la[a], na, nb;
        if (b < 0) continue;
        na = A->cn[a];
        nb = B->cn[b];
        if (!na || !nb || na > c->bcap || nb > c->bcap) continue;
        if (m == M_CSEQ) {
            if (na == nb) prop_aligned(c, A->cid + A->co[a], B->cid + B->co[b], na, m);
            continue;
        }
        {
            int *da = c->buf1, *db = c->buf2, nda, ndb, i;
            c->stamp++;
            nda = dedup_list(A->cid + A->co[a], na, da, c->stA, c->stamp);
            ndb = dedup_list(B->cid + B->co[b], nb, db, c->stB, c->stamp);
            if (!nda || !ndb) continue;
            if (m == M_CDEDUP) {
                if (nda == ndb && (nda != na || ndb != nb)) prop_aligned(c, da, db, nda, m);
                continue;
            }
            /* call_gap / call_gap_sim: anchors are the linked callees whose partners are
               called by b, reduced to the longest order-preserving chain; between
               consecutive anchors the unlinked callees of both sides form a gap, aligned
               position-wise when the lengths agree (call_gap) or by similarity DP
               (call_gap_sim) */
            if (nda > 512 || ndb > 512) continue;
            for (i = 0; i < ndb; i++) c->cntB[db[i]] = i;
            {
                static int ai[514], aj[514], len[514], prv[514], chain_i[514], chain_j[514];
                static int ga[512], gb[512];
                int nan = 0, best = -1, nch = 0, k, q;
                for (i = 0; i < nda; i++) {
                    int y = c->la[da[i]];
                    if (y < 0 || c->stB[y] != c->stamp) continue;
                    ai[nan] = i;
                    aj[nan] = c->cntB[y];
                    nan++;
                }
                if (!nan) continue; /* no anchor: call_seq / call_dedup territory */
                for (k = 0; k < nan; k++) { /* O(n^2) LIS on aj */
                    len[k] = 1;
                    prv[k] = -1;
                    for (q = 0; q < k; q++)
                        if (aj[q] < aj[k] && len[q] + 1 > len[k]) { len[k] = len[q] + 1; prv[k] = q; }
                    if (best < 0 || len[k] > len[best]) best = k;
                }
                for (k = best; k >= 0; k = prv[k]) nch++;
                q = nch;
                for (k = best; k >= 0; k = prv[k]) { q--; chain_i[q + 1] = ai[k]; chain_j[q + 1] = aj[k]; }
                chain_i[0] = -1;
                chain_j[0] = -1;
                chain_i[nch + 1] = nda;
                chain_j[nch + 1] = ndb;
                for (k = 0; k <= nch; k++) {
                    int ngA = 0, ngB = 0, t;
                    for (t = chain_i[k] + 1; t < chain_i[k + 1]; t++) if (c->la[da[t]] < 0) ga[ngA++] = da[t];
                    for (t = chain_j[k] + 1; t < chain_j[k + 1]; t++) if (c->lb[db[t]] < 0) gb[ngB++] = db[t];
                    if (!ngA || !ngB) continue;
                    if (m == M_CGAP) {
                        if (ngA == ngB)
                            for (t = 0; t < ngA; t++) add_prop(c, ga[t], gb[t], 1, m);
                    } else if (ngA <= 16 && ngB <= 16)
                        align_lists(c, ga, ngA, gb, ngB, g_sim_T, m);
                }
            }
        }
    }
    return resolve(c, m, UNANIMOUS, 1);
}

/* unique unlinked callee shared by all linked callers of x (direction X->Y) */
static int caller_cand(Ctx *c, int dirAB, int x)
{
    Img *X = dirAB ? c->A : c->B, *Y = dirAB ? c->B : c->A;
    int *lx = dirAB ? c->la : c->lb, *ly = dirAB ? c->lb : c->la;
    int *stY = dirAB ? c->stB : c->stA, *cntY = dirAB ? c->cntB : c->cntA, *lastY = dirAB ? c->lastB : c->lastA;
    int i, j, np = 0, first = -1, res = -1, nres = 0, st;
    st = ++c->stamp;
    for (i = 0; i < X->rn[x] && np < 16; i++) {
        int p = X->rid[X->ro[x] + i], pp;
        if (lx[p] < 0) continue;
        pp = lx[p];
        np++;
        if (first < 0) first = pp;
        for (j = 0; j < Y->cn[pp]; j++) {
            int y = Y->cid[Y->co[pp] + j];
            if (y < 0 || ly[y] >= 0) continue;
            if (stY[y] != st) { stY[y] = st; cntY[y] = 0; lastY[y] = -1; }
            if (lastY[y] == np) continue;
            lastY[y] = np;
            cntY[y]++;
        }
    }
    if (!np) return -1;
    for (j = 0; j < Y->cn[first]; j++) {
        int y = Y->cid[Y->co[first] + j];
        if (y < 0 || ly[y] >= 0 || stY[y] != st) continue;
        if (cntY[y] == np && lastY[y] != -2) {
            lastY[y] = -2;
            res = y;
            nres++;
        }
    }
    return nres == 1 ? res : -1;
}
static int m_caller(Ctx *c)
{
    Img *A = c->A;
    int a;
    for (a = 0; a < A->n; a++) {
        int b;
        if (c->la[a] >= 0 || !A->rn[a]) continue;
        b = caller_cand(c, 1, a);
        if (b < 0) continue;
        if (caller_cand(c, 0, b) != a) continue;
        add_prop(c, a, b, 1, M_CALLER);
    }
    return resolve(c, M_CALLER, UNANIMOUS, 1);
}
static int m_ustr_rel(Ctx *c)
{
    Img *A = c->A, *B = c->B;
    int s, i, j;
    for (s = 0; s < G_str.n; s++) {
        int k = A->strcnt[s], ua = -1, ub = -1, ca = 0, cb = 0, ok = 1;
        if (g_generic[s] || k < 2 || k > 8 || B->strcnt[s] != k) continue;
        for (i = 0; i < k; i++) {
            int x = A->suid[A->suo[s] + i];
            if (c->la[x] < 0) { ua = x; ca++; continue; }
            for (j = 0; j < k; j++)
                if (B->suid[B->suo[s] + j] == c->la[x]) break;
            if (j == k) ok = 0;
        }
        for (i = 0; i < k; i++) {
            int y = B->suid[B->suo[s] + i];
            if (c->lb[y] < 0) { ub = y; cb++; }
        }
        if (ok && ca == 1 && cb == 1) add_prop(c, ua, ub, 1, M_USTRREL);
    }
    return resolve(c, M_USTRREL, 2.0, 1);
}
static int m_objrun(Ctx *c)
{
    Img *A = c->A, *B = c->B;
    int a, prev = -1;
    if (!B->objid) return 0;
    for (a = 0; a < A->n; a++) {
        if (c->la[a] < 0) continue;
        if (prev >= 0 && a - prev > 1 && a - prev - 1 <= 32) {
            int b1 = c->la[prev], b2 = c->la[a], k = a - prev - 1, t, ok = 1;
            if (b2 - b1 - 1 == k && B->objid[b1] >= 0 && B->objid[b1] == B->objid[b2]) {
                for (t = b1 + 1; t < b2; t++)
                    if (B->objid[t] != B->objid[b1] || c->lb[t] >= 0) ok = 0;
                if (ok)
                    for (t = 0; t < k; t++) add_prop(c, prev + 1 + t, b1 + 1 + t, 1, M_OBJRUN);
            }
        }
        prev = a;
    }
    return resolve(c, M_OBJRUN, UNANIMOUS, 1);
}

static int name_cat(Img *A, int a, Img *B, int b);
static int g_debug, g_calib_only;
/* debug dump of one pair's links (evidence directory only) */
static void dump_links(Ctx *c, const char *dir, const char *tag)
{
    char p[800];
    FILE *f;
    int a;
    snprintf(p, sizeof p, "%s/debug_%s.tsv", dir, tag);
    f = fopen(p, "wb");
    if (!f) return;
    fprintf(f, "a_addr\tb_addr\tmethod\tcat\ta_size\tb_size\ta_ncall\tb_ncall\ta_name\tb_name\n");
    for (a = 0; a < c->A->n; a++) {
        int b = c->la[a];
        if (b < 0) continue;
        fprintf(f, "0x%08x\t0x%08x\t%s\t%d\t%u\t%u\t%d\t%d\t%s\t%s\n", c->A->addr[a], c->B->addr[b], MN[c->meth[a]],
                name_cat(c->A, a, c->B, b), c->A->size[a], c->B->size[b], c->A->cn[a], c->B->cn[b],
                c->A->nn && c->A->nn[a] ? c->A->nm[c->A->no[a]].qual : "",
                c->B->nn && c->B->nn[b] ? c->B->nm[c->B->no[b]].qual : "");
    }
    fclose(f);
}

static int count_links(Ctx *c)
{
    int i, n = 0;
    for (i = 0; i < c->A->n; i++) n += c->la[i] >= 0;
    return n;
}

/* --- feature similarity (distance; 0 = identical shape) */

static double g_sim_T = 1.0;     /* max distance for a similarity match */
static double g_sim_margin = 0.6; /* best <= margin * second best */
static double g_sim_wnb = 1.5;    /* weight of call-graph neighbourhood disagreement */
static double g_obj_T = 0.6;      /* max distance inside object gaps */
static int g_obj_open = 1;        /* also align open-ended object gaps */

static double lr(double x, double y) { double v = log(x / y); return v < 0 ? -v : v; }
static double jacc_tok(Img *A, Img *B, int a, int b, char kind, int *has)
{
    int i, j, na = 0, nb = 0, in = 0;
    const int *ta = A->tid + A->to[a], *tb = B->tid + B->to[b];
    for (i = 0; i < A->tn[a]; i++) if (G_tok.s[ta[i]][0] == kind && B->tokcnt[ta[i]] > 0) na++;
    for (j = 0; j < B->tn[b]; j++) if (G_tok.s[tb[j]][0] == kind && A->tokcnt[tb[j]] > 0) nb++;
    *has = na + nb > 0;
    if (!na || !nb) return 0;
    i = j = 0;
    while (i < A->tn[a] && j < B->tn[b]) {
        if (ta[i] == tb[j]) { if (G_tok.s[ta[i]][0] == kind) in++; i++; j++; }
        else if (ta[i] < tb[j]) i++;
        else j++;
    }
    return (double)in / (double)(na + nb - in);
}
static double sim_dist(Ctx *c, int a, int b)
{
    Img *A = c->A, *B = c->B;
    double d = 0, J;
    int sa[256], sb[256], na, nb, in, has;
    d += 1.0 * lr((B->size[b] + 8.0), c->szscale * (A->size[a] + 8.0));
    d += 0.7 * lr((B->ninsn[b] + 2.0), c->inscale * (A->ninsn[a] + 2.0));
    d += 0.5 * lr(B->nbb[b] + 1.0, A->nbb[a] + 1.0);
    d += 0.5 * lr(B->dcn[b] + 1.0, A->dcn[a] + 1.0);
    d += 0.2 * lr(B->rn[b] + 1.0, A->rn[a] + 1.0);
    na = svocab(A, B, a, sa, 256);
    nb = svocab(B, A, b, sb, 256);
    if (na || nb) {
        in = inter_sorted(sa, na, sb, nb);
        d += 1.5 * (1.0 - (double)in / (double)(na + nb - in));
    }
    J = jacc_tok(A, B, a, b, 'v', &has);
    if (has) d += 1.0 * (1.0 - J);
    J = jacc_tok(A, B, a, b, 'k', &has);
    if (has) d += 0.5 * (1.0 - J);
    /* neighbourhood consistency: linked callees / callers of a that map onto
       callees / callers of b */
    {
        int pass;
        for (pass = 0; pass < 2; pass++) {
            const int *la_ = pass ? A->rid + A->ro[a] : A->cid + A->co[a];
            const int *lb_ = pass ? B->rid + B->ro[b] : B->cid + B->co[b];
            int nla = pass ? A->rn[a] : A->cn[a], nlb = pass ? B->rn[b] : B->cn[b], i, j, ka = 0, kb = 0, mm = 0;
            if (nla > 64) nla = 64;
            if (nlb > 64) nlb = 64;
            for (j = 0; j < nlb; j++) if (lb_[j] >= 0 && c->lb[lb_[j]] >= 0) kb++;
            for (i = 0; i < nla; i++) {
                int x = la_[i], y;
                if (x < 0 || c->la[x] < 0) continue;
                ka++;
                y = c->la[x];
                for (j = 0; j < nlb; j++) if (lb_[j] == y) { mm++; break; }
            }
            if (ka || kb) {
                double cons = (double)mm / (double)(ka > kb ? ka : kb);
                if (cons > 1) cons = 1;
                d += g_sim_wnb * (1.0 - cons);
            }
        }
    }
    return d;
}
static int cmp_dbl(const void *x, const void *y)
{
    double a = *(const double *)x, b = *(const double *)y;
    return a < b ? -1 : a > b;
}
static void calc_scale(Ctx *c)
{
    int a, n = 0;
    double *r1 = xmalloc((c->A->n + 1) * sizeof(double)), *r2 = xmalloc((c->A->n + 1) * sizeof(double));
    for (a = 0; a < c->A->n; a++) {
        int b = c->la[a];
        if (b < 0 || c->A->size[a] < 16) continue;
        r1[n] = (c->B->size[b] + 8.0) / (c->A->size[a] + 8.0);
        r2[n] = (c->B->ninsn[b] + 2.0) / (c->A->ninsn[a] + 2.0);
        n++;
    }
    c->szscale = c->inscale = 1.0;
    if (n > 50) {
        qsort(r1, n, sizeof(double), cmp_dbl);
        qsort(r2, n, sizeof(double), cmp_dbl);
        c->szscale = r1[n / 2];
        c->inscale = r2[n / 2];
    }
    free(r1);
    free(r2);
}

/* mutual-best similarity matching between two small candidate sets (with
   relative position as an extra feature) */
static void sim_match_sets(Ctx *c, const int *xa, int na, const int *yb, int nb, int m, int use_pos)
{
    static double D[48][48];
    int i, j;
    if (na > 48 || nb > 48 || !na || !nb) return;
    for (i = 0; i < na; i++)
        for (j = 0; j < nb; j++) {
            double d = sim_dist(c, xa[i], yb[j]);
            if (use_pos && na > 1 && nb > 1) {
                double p = (double)i / (na - 1) - (double)j / (nb - 1);
                d += 0.5 * (p < 0 ? -p : p);
            }
            D[i][j] = d;
        }
    for (i = 0; i < na; i++) {
        int bj = -1, k;
        double d1 = 1e9, d2 = 1e9, e1 = 1e9, e2 = 1e9;
        for (j = 0; j < nb; j++) {
            if (D[i][j] < d1) { d2 = d1; d1 = D[i][j]; bj = j; }
            else if (D[i][j] < d2) d2 = D[i][j];
        }
        if (bj < 0 || d1 > g_sim_T || d1 > g_sim_margin * d2) continue;
        for (k = 0; k < na; k++) {
            if (D[k][bj] < e1) { e2 = e1; e1 = D[k][bj]; }
            else if (D[k][bj] < e2) e2 = D[k][bj];
        }
        if (D[i][bj] > e1 || e1 > g_sim_margin * e2) continue;
        add_prop(c, xa[i], yb[bj], 1, m);
    }
}
static int unlinked_list(const int *l, int n, int *out, int cap, int *link, int *st, int stamp)
{
    int i, k = 0;
    for (i = 0; i < n && k < cap; i++) {
        int x = l[i];
        if (x < 0 || link[x] >= 0 || st[x] == stamp) continue;
        st[x] = stamp;
        out[k++] = x;
    }
    return k;
}
static int m_callsim(Ctx *c, int callers)
{
    Img *A = c->A, *B = c->B;
    int a, xa[64], yb[64];
    for (a = 0; a < A->n; a++) {
        int b = c->la[a], na, nb;
        if (b < 0) continue;
        c->stamp++;
        if (!callers) {
            na = unlinked_list(A->cid + A->co[a], A->cn[a], xa, 64, c->la, c->stA, c->stamp);
            nb = unlinked_list(B->cid + B->co[b], B->cn[b], yb, 64, c->lb, c->stB, c->stamp);
        } else {
            na = unlinked_list(A->rid + A->ro[a], A->rn[a], xa, 64, c->la, c->stA, c->stamp);
            nb = unlinked_list(B->rid + B->ro[b], B->rn[b], yb, 64, c->lb, c->stB, c->stamp);
        }
        if (na > 48 || nb > 48) continue;
        sim_match_sets(c, xa, na, yb, nb, callers ? M_RSIM : M_CSIM, !callers);
    }
    return resolve(c, callers ? M_RSIM : M_CSIM, UNANIMOUS, 1);
}

/* DP alignment of two ordered unlinked lists (monotonic, matches need
   distance <= TT) */
static void align_lists(Ctx *c, const int *xa, int na, const int *yb, int nb, double TT, int m)
{
    static double S[34][34];
    static u8 T[34][34];
    int i, j;
    if (na > 32 || nb > 32 || !na || !nb) return;
    for (i = 0; i <= na; i++) { S[i][0] = 0; T[i][0] = 1; }
    for (j = 0; j <= nb; j++) { S[0][j] = 0; T[0][j] = 2; }
    for (i = 1; i <= na; i++)
        for (j = 1; j <= nb; j++) {
            double d = sim_dist(c, xa[i - 1], yb[j - 1]), best = S[i - 1][j];
            u8 t = 1;
            if (S[i][j - 1] > best) { best = S[i][j - 1]; t = 2; }
            if (d <= TT && S[i - 1][j - 1] + (TT - d) + 0.01 > best) {
                best = S[i - 1][j - 1] + (TT - d) + 0.01;
                t = 3;
            }
            S[i][j] = best;
            T[i][j] = t;
        }
    i = na;
    j = nb;
    while (i > 0 && j > 0) {
        if (T[i][j] == 3) { add_prop(c, xa[i - 1], yb[j - 1], 1, m); i--; j--; }
        else if (T[i][j] == 1) i--;
        else j--;
    }
}
static void align_runs(Ctx *c, int a0, int na, int b0, int nb, int m)
{
    int xa[32], yb[32], i;
    if (na > 32 || nb > 32) return;
    for (i = 0; i < na; i++) xa[i] = a0 + i;
    for (i = 0; i < nb; i++) yb[i] = b0 + i;
    align_lists(c, xa, na, yb, nb, g_obj_T, m);
}
static int m_objsim(Ctx *c, int open)
{
    int open_ = open; /* two-sided gaps (0) or open-ended (1) */
    Img *A = c->A, *B = c->B;
    int a, prev = -1;
    if (!B->objid) return 0;
    for (a = 0; a <= A->n; a++) {
        if (a < A->n && c->la[a] < 0) continue;
        if (prev >= 0 && a - prev > 1) {
            int b1 = c->la[prev], ka = a - prev - 1, ob = B->objid[b1], t, kb = 0;
            int b2 = a < A->n ? c->la[a] : -1;
            /* the reference run after b1: unlinked functions of b1's object */
            for (t = b1 + 1; t < B->n && kb < 32 && c->lb[t] < 0 && ob >= 0 && B->objid[t] == ob; t++) kb++;
            if (b2 > b1 && b2 - b1 - 1 == kb && B->objid[b2] == ob) {
                if (!open_ && ka != kb) align_runs(c, prev + 1, ka < 32 ? ka : 32, b1 + 1, kb, M_OBJSIM);
            } else if (open_ && kb && ka) {
                /* open-ended: align the start of the gap with the rest of b1's object run */
                align_runs(c, prev + 1, ka < kb + 4 ? ka : kb + 4, b1 + 1, kb, M_OBJOPEN);
            }
        }
        if (a < A->n) prev = a;
    }
    /* and backwards: the run before each linked pair's partner */
    prev = A->n;
    for (a = A->n - 1; a >= -1; a--) {
        if (a >= 0 && c->la[a] < 0) continue;
        if (prev < A->n && prev - a > 1) {
            int b2 = c->la[prev], ka = prev - a - 1, ob = B->objid[b2], t, kb = 0;
            int b1 = a >= 0 ? c->la[a] : -1;
            for (t = b2 - 1; t >= 0 && kb < 32 && c->lb[t] < 0 && ob >= 0 && B->objid[t] == ob; t--) kb++;
            if (open_ && !(b1 >= 0 && b1 < b2 && b2 - b1 - 1 == kb && B->objid[b1] == ob) && kb && ka) {
                int n = ka < kb + 4 ? ka : kb + 4;
                align_runs(c, prev - n, n, b2 - kb, kb, M_OBJOPEN);
            }
        }
        if (a >= 0) prev = a;
    }
    return resolve(c, open ? M_OBJOPEN : M_OBJSIM, UNANIMOUS, 1);
}

static int m_udata(Ctx *c);
static void propagate(Ctx *c)
{
    for (;;) {
        int ch = 0, k;
        for (;;) {
            int k2 = 0;
            do {
                k = m_calls(c, M_CSEQ);
                k += m_calls(c, M_CDEDUP);
                k += m_calls(c, M_CGAP);
                k2 += k;
            } while (k);
            k2 += m_caller(c);
            k2 += m_ustr_rel(c);
            k2 += m_udata(c);
            k2 += m_strset(c);
            ch += k2;
            if (!k2) break;
        }
        k = m_calls(c, M_CGAPSIM);
        if (!k) k = m_callsim(c, 0);
        if (!k) k = m_callsim(c, 1);
        if (!k) break;
    }
}

static void run_match(Ctx *c)
{
    m_vtables(c, 0);
    m_vtables(c, 1);
    m_ustr(c);
    m_utok(c, 'v', M_UVREF);
    m_hash(c);
    m_strset(c);
    m_utok(c, 'k', M_UCONST);
    m_utok(c, 'i', M_UIMP);
    calc_scale(c);
    propagate(c);
    info("  %s -> %s: phase 1 %d links (size scale %.2f)", c->A->id, c->B->id, count_links(c), c->szscale);
    c->phase2 = 1;
    for (;;) {
        int k = m_objrun(c);
        if (!k) k = m_objsim(c, 0);
        if (!k) break;
        propagate(c);
    }
    info("  %s -> %s: phase 2 %d links", c->A->id, c->B->id, count_links(c));
    if (g_obj_open) {
        c->phase2 = 2;
        for (;;) {
            int k = m_objrun(c);
            if (!k) k = m_objsim(c, 0);
            if (!k) k = m_objsim(c, 1);
            if (!k) break;
            propagate(c);
        }
        info("  %s -> %s: phase 3 %d links", c->A->id, c->B->id, count_links(c));
    }
}

/* ------------------------------------------------------------- evaluation */

/* 3 exact, 2 same template member, 1 same method name, 0 different, -1 unnamed */
static int name_cat(Img *A, int a, Img *B, int b)
{
    int i, j, best = 0;
    if (!A->nn || !B->nn || !A->nn[a] || !B->nn[b]) return -1;
    for (i = 0; i < A->nn[a]; i++)
        for (j = 0; j < B->nn[b]; j++) {
            NameRec *x = &A->nm[A->no[a] + i], *y = &B->nm[B->no[b] + j];
            if (x->norm == y->norm) return 3;
            if (x->tnorm == y->tnorm) { if (best < 2) best = 2; }
            else if (x->meth == y->meth && best < 1) best = 1;
        }
    return best;
}

typedef struct {
    long n, eval, cat[4];
} Score;
static void score_ctx(Ctx *c, Score *s)
{
    int a;
    memset(s, 0, sizeof(Score) * NM);
    for (a = 0; a < c->A->n; a++) {
        int m = c->meth[a], k;
        if (c->la[a] < 0) continue;
        s[m].n++;
        k = name_cat(c->A, a, c->B, c->la[a]);
        if (k < 0) continue;
        s[m].eval++;
        s[m].cat[k]++;
    }
}

/* data links through positional datarefs of linked function pairs */
typedef struct {
    u32 da, db;
    int w;
} DProp;
static int cmp_dprop(const void *x, const void *y)
{
    const DProp *p = x, *q = y;
    if (p->da != q->da) return p->da < q->da ? -1 : 1;
    return p->db < q->db ? -1 : p->db > q->db;
}
static int cmp_dprop_b(const void *x, const void *y)
{
    const DProp *p = x, *q = y;
    if (p->db != q->db) return p->db < q->db ? -1 : 1;
    return p->w > q->w ? -1 : p->w < q->w;
}
typedef struct {
    u32 *da, *db;
    int *votes, n;
} DLinks;
static void data_links(Ctx *c, DLinks *out)
{
    Img *A = c->A, *B = c->B;
    DProp *p = NULL, *bq;
    int np = 0, cap = 0, a, i, j, k, n;
    Map bbest = {0};
    for (a = 0; a < A->n; a++) {
        int b = c->la[a];
        if (b < 0 || A->drn[a] != B->drn[b]) continue;
        for (i = 0; i < A->drn[a]; i++) {
            if (np == cap) { cap = cap ? cap * 2 : 65536; p = xrealloc(p, cap * sizeof(DProp)); }
            p[np].da = A->dra[A->dro[a] + i];
            p[np].db = B->dra[B->dro[b] + i];
            p[np].w = 1;
            np++;
        }
    }
    qsort(p, np, sizeof(DProp), cmp_dprop);
    for (i = 0, k = 0; i < np; i++) {
        if (k && p[k - 1].da == p[i].da && p[k - 1].db == p[i].db) p[k - 1].w++;
        else p[k++] = p[i];
    }
    n = k;
    /* B side: unanimous source */
    bq = xmalloc((n + 1) * sizeof(DProp));
    memcpy(bq, p, n * sizeof(DProp));
    qsort(bq, n, sizeof(DProp), cmp_dprop_b);
    for (i = 0; i < n; i = j) {
        for (j = i; j < n && bq[j].db == bq[i].db; j++) {}
        map_put(&bbest, bq[i].db, j - i == 1 ? 1 : 0);
    }
    out->da = xmalloc((n + 1) * sizeof(u32));
    out->db = xmalloc((n + 1) * sizeof(u32));
    out->votes = xmalloc((n + 1) * sizeof(int));
    out->n = 0;
    for (i = 0; i < n; i = j) {
        int uniq;
        for (j = i; j < n && p[j].da == p[i].da; j++) {}
        if (j - i != 1) continue;
        if (!map_get(&bbest, p[i].db, &uniq) || !uniq) continue;
        out->da[out->n] = p[i].da;
        out->db[out->n] = p[i].db;
        out->votes[out->n] = p[i].w;
        out->n++;
    }
    free(p);
    free(bq);
    free(bbest.k);
    free(bbest.v);
}

/* udata: a linked global (through positional datarefs of linked pairs) with the
   same number of users on both sides, all but one linked consistently */
static int m_udata(Ctx *c)
{
    Img *A = c->A, *B = c->B;
    DLinks d;
    int i;
    data_links(c, &d);
    for (i = 0; i < d.n; i++) {
        int fa, fb, ka = 0, kb = 0, ua = -1, ub = -1, na = 0, nb = 0, ok = 1, j, t;
        if (!map_get(&A->dfirst, d.da[i], &fa) || !map_get(&B->dfirst, d.db[i], &fb)) continue;
        while (fa + ka < A->ndk && A->dk[fa + ka] == d.da[i]) ka++;
        while (fb + kb < B->ndk && B->dk[fb + kb] == d.db[i]) kb++;
        if (ka != kb || ka > 16) continue;
        for (j = 0; j < ka; j++) {
            int x = A->dfn[fa + j];
            if (c->la[x] < 0) { ua = x; na++; continue; }
            for (t = 0; t < kb; t++) if (B->dfn[fb + t] == c->la[x]) break;
            if (t == kb) ok = 0;
        }
        for (j = 0; j < kb; j++) if (c->lb[B->dfn[fb + j]] < 0) { ub = B->dfn[fb + j]; nb++; }
        if (ok && na == 1 && nb == 1) add_prop(c, ua, ub, 1, M_UDATA);
    }
    free(d.da);
    free(d.db);
    free(d.votes);
    return resolve(c, M_UDATA, 2.0, 1);
}

