static long g_eval[NM];

static int tier_from(double prec, long n)
{
    if (n < 20) return T_LOW;
    if (prec >= 0.99) return T_HIGH;
    if (prec >= 0.90) return T_MED;
    return T_LOW;
}

/* ---------------------------------------------------------------- recipe */

typedef struct {
    u32 *addr;
    char **sym;
    int n;
} Recipe;
static void load_recipe(const char *path, Recipe *r)
{
    size_t len;
    char *b = slurp(path, &len), *p;
    int cap = 0;
    if (!b) die("missing recipe %s", path);
    r->n = 0;
    p = b;
    while ((p = strstr(p, "\"address\": \"0x")) != NULL) {
        char *s, *e;
        u32 a = (u32)strtoul(p + 14, NULL, 16);
        if (r->n == cap) {
            cap = cap ? cap * 2 : 65536;
            r->addr = xrealloc(r->addr, cap * sizeof(u32));
            r->sym = xrealloc(r->sym, cap * sizeof(char *));
        }
        r->addr[r->n] = a;
        r->sym[r->n] = NULL;
        s = strstr(p, "\"symbol\": \"");
        e = strchr(p + 14, '}');
        if (s && (!e || s < e)) {
            char *q = s + 11, *qe = strchr(q, '"');
            if (qe) r->sym[r->n] = xstrndup(q, (size_t)(qe - q));
        }
        r->n++;
        p += 14;
    }
    free(b);
}

/* f3_decomp placeholder symbols carry an address-derived token (FUN_00401190, f3m_00401bb0, Map_00a4da90) */
static int sym_placeholder(const char *s)
{
    const char *p;
    if (strstr(s, "FUN_")) return 1;
    for (p = s; *p; p++) {
        int k = 0;
        if (*p != '_') continue;
        while (k < 8 && isxdigit((u8)p[1 + k])) k++;
        if (k >= 6 && !isxdigit((u8)p[1 + k])) return 1;
    }
    return 0;
}

/* simple MSVC demangle of the qualified name (no templates); NULL if unsupported */
static int demangle_qual(const char *d, char *out, size_t cap)
{
    const char *p = d, *parts[16];
    size_t plen[16];
    int np = 0, i;
    char special = 0, sp2 = 0;
    size_t o = 0;
    if (*p != '?') return 0;
    p++;
    if (*p == '?') {
        p++;
        if (*p == '_') { sp2 = p[1]; p += 2; special = '_'; }
        else special = *p++;
    }
    while (*p && *p != '@' && np < 16) {
        const char *s = p;
        if (*p == '?') return 0; /* templates / nested */
        while (*p && *p != '@') p++;
        parts[np] = s;
        plen[np] = (size_t)(p - s);
        np++;
        if (*p == '@') p++;
    }
    if (!np) return 0;
    /* parts: [name] class ns ... (name absent for special) */
    for (i = np - 1; i >= (special ? 0 : 1); i--) {
        if (o + plen[i] + 3 >= cap) return 0;
        memcpy(out + o, parts[i], plen[i]);
        o += plen[i];
        out[o++] = ':';
        out[o++] = ':';
    }
    out[o] = 0;
    if (!special) {
        if (o + plen[0] + 1 >= cap) return 0;
        memcpy(out + o, parts[0], plen[0]);
        o += plen[0];
        out[o] = 0;
    } else {
        const char *cls = parts[0];
        size_t cl = plen[0];
        if (special == '0' || special == '1') {
            if (o + cl + 2 >= cap) return 0;
            if (special == '1') out[o++] = '~';
            memcpy(out + o, cls, cl);
            o += cl;
            out[o] = 0;
        } else if (special == '_' && sp2 == 'G') {
            snprintf(out + o, cap - o, "`scalar deleting destructor'");
        } else if (special == '_' && sp2 == 'E') {
            snprintf(out + o, cap - o, "`vector deleting destructor'");
        } else
            return 0;
    }
    return 1;
}

