static u8 *make_hide(int n, u32 *addr)
{
    u8 *h = xcalloc(n, 1);
    int i;
    for (i = 0; i < n; i++) h[i] = (u8)(hmix(addr[i] ^ 0x5bd1e995u) & 1);
    return h;
}

typedef struct {
    long hidden, recovered, correct, wrong_by[NM], right_by[NM];
} Holdout;
static void holdout_run(Img *A, Img *B, Ctx *full, Holdout *h)
{
    Ctx *c = ctx_new(A, B);
    int a;
    memset(h, 0, sizeof *h);
    c->hideA = make_hide(A->n, A->addr);
    run_match(c);
    for (a = 0; a < A->n; a++) {
        if (!c->hideA[a] || full->la[a] < 0 || !is_anchor(full->meth[a])) continue;
        h->hidden++;
        if (c->la[a] < 0) continue;
        h->recovered++;
        if (c->la[a] == full->la[a]) { h->correct++; h->right_by[c->meth[a]]++; }
        else h->wrong_by[c->meth[a]]++;
    }
    free(c->hideA);
    ctx_free(c);
}
static void write_holdout(FILE *f, const char *title, Holdout *h)
{
    int m;
    fprintf(f, "\n### Holdout: %s\n\nAnchor links of a random half of the functions were hidden (anchors not proposed for them); "
               "the rest of the pipeline then ran unchanged.\n\n", title);
    fprintf(f, "- hidden anchor links: %ld\n- recovered by propagation: %ld (%.1f%%)\n- recovered with the same partner: %ld (%.2f%% of recovered)\n\n",
            h->hidden, h->recovered, h->hidden ? 100.0 * h->recovered / h->hidden : 0.0, h->correct,
            h->recovered ? 100.0 * h->correct / h->recovered : 0.0);
    fprintf(f, "| recovering method | same partner | different partner | agreement |\n|---|---:|---:|---:|\n");
    for (m = 1; m < NM; m++)
        if (h->right_by[m] + h->wrong_by[m])
            fprintf(f, "| %s | %ld | %ld | %.2f%% |\n", MN[m], h->right_by[m], h->wrong_by[m],
                    100.0 * h->right_by[m] / (h->right_by[m] + h->wrong_by[m]));
}

/* "Class::Method" prefix of an F3 string literal; returns 1 and fills out */
static int string_selfname(const char *s, char *out, size_t cap)
{
    const char *p = s;
    size_t n;
    int comps = 0;
    if (!isalpha((u8)*p) && *p != '_') return 0;
    for (;;) {
        while (is_idc((u8)*p)) p++;
        comps++;
        if (p[0] == ':' && p[1] == ':' && (isalpha((u8)p[2]) || p[2] == '_' || p[2] == '~')) {
            p += 2;
            if (*p == '~') p++;
            continue;
        }
        break;
    }
    if (comps < 2) return 0;
    if (*p && !strchr(":( ,-.!'\\[", *p)) return 0;
    n = (size_t)(p - s);
    if (n >= cap) return 0;
    memcpy(out, s, n);
    out[n] = 0;
    return 1;
}

static int valid_ident(const char *s)
{
    if (!(isalpha((u8)*s) || *s == '_')) return 0;
    for (s++; *s; s++)
        if (!(isalnum((u8)*s) || *s == '_')) return 0;
    return 1;
}
/* placeholder-like type names, the same rule as f3rename's placeholder_type */
static int type_placeholder(const char *s)
{
    static const char *pre[] = {"FUN_", "DAT_", "Unk", "UNK_", "unk_", "Unknown", "Stub", "Fnv", "f3m_", NULL};
    size_t n = strlen(s), i, k;
    for (i = 0; pre[i]; i++) if (!strncmp(s, pre[i], strlen(pre[i]))) return 1;
    for (i = 0; i + 8 <= n; i++) {
        if (i > 0 && s[i - 1] != '_') continue;
        for (k = 0; k < 8 && isxdigit((u8)s[i + k]); k++) {}
        if (k == 8 && (i + 8 == n || s[i + 8] == '_')) return 1;
    }
    if (n > 6 && !strcmp(s + n - 6, "_shell")) return 1;
    return 0;
}

/* class part of a normalized, template-stripped qualified name ("" for free functions) */
static const char *class_of(const char *q)
{
    static char b[4096];
    const char *lc = last_comp(q);
    size_t n = lc > q + 2 ? (size_t)(lc - q - 2) : 0;
    if (n >= sizeof b) n = sizeof b - 1;
    memcpy(b, q, n);
    b[n] = 0;
    return b;
}
/* "Class::Method..." or "Class::" at the start of a literal: the class it names (normalized),
   the full name when a method follows, and whether it does */
static int string_classref(const char *s, char *cls, size_t ccap, char *full, size_t fcap, int *has_m)
{
    const char *p = s, *lastsep = NULL;
    size_t n;
    int comps = 0;
    if (!isalpha((u8)*p) && *p != '_') return 0;
    for (;;) {
        while (is_idc((u8)*p)) p++;
        comps++;
        if (p[0] == ':' && p[1] == ':') {
            lastsep = p;
            p += 2;
            if (*p == '~') p++;
            if (isalpha((u8)*p) || *p == '_') continue;
            /* "Class::" followed by something else: class only */
            n = (size_t)(lastsep - s);
            if (n >= ccap) return 0;
            memcpy(cls, s, n);
            cls[n] = 0;
            full[0] = 0;
            *has_m = 0;
            return 1;
        }
        break;
    }
    if (comps < 2 || !lastsep) return 0;
    if (*p && !strchr(":( ,-.!'\\[", *p)) return 0;
    n = (size_t)(lastsep - s);
    if (n >= ccap || (size_t)(p - s) >= fcap) return 0;
    memcpy(cls, s, n);
    cls[n] = 0;
    memcpy(full, s, (size_t)(p - s));
    full[p - s] = 0;
    *has_m = 1;
    return 1;
}

